const labFields = [
  ['name', 'Lab name', 'HTB practice'], ['target', 'Target IP or hostname', '10.10.10.10'],
  ['domain', 'AD domain', 'example.local'], ['dcIp', 'DC IP', '10.10.10.5'],
  ['dcHost', 'DC hostname (FQDN)', 'dc01.example.local'], ['username', 'Domain username', 'student']
];
const shellQuote = value => "'" + value.replace(/'/g, "'\\''") + "'";
const cypherQuote = value => '"' + value.replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
const labSlug = value => value.toLowerCase().replace(/[^a-z0-9_-]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60) || 'lab';
const validHost = value => {
  if (!value || value.length > 253) return false;
  if (/^[0-9.]+$/.test(value)) return value.split('.').length === 4 && value.split('.').every(x => /^\d{1,3}$/.test(x) && +x <= 255);
  return value.split('.').every(x => /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i.test(x));
};
const fieldError = (key, value) => {
  if (!value.trim()) return 'Required for this command';
  if (/[\x00-\x1f\x7f]/.test(value)) return 'Use a single line without control characters';
  if (key === 'name') return value.length <= 100 ? '' : 'Use 100 characters or fewer';
  if (key === 'username') return /^[a-z0-9_.@$-]{1,100}$/i.test(value) ? '' : 'Enter the username only, without the domain or spaces';
  if (key === 'dcIp') return /^[0-9.]+$/.test(value) && validHost(value) ? '' : 'Enter a valid IPv4 address';
  if (!validHost(value)) return 'Enter a hostname or IPv4 address using letters, numbers, dots, and hyphens';
  if (['domain', 'dcHost'].includes(key) && (!value.includes('.') || /^[0-9.]+$/.test(value))) return 'Enter a full DNS name, such as example.local';
  return '';
};
const renderLabCommand = (code, values) => {
  const required = new Set();
  const dependencies = {folder: ['name'], identity: ['domain', 'username'], principal: ['username', 'domain']};
  const rendered = code.replace(/\{\{(\w+)\}\}/g, (token, key) => {
    const keys = dependencies[key] || [key];
    keys.forEach(k => required.add(k));
    if (keys.some(k => fieldError(k, values[k] || ''))) return token;
    if (key === 'folder') return labSlug(values.name);
    if (key === 'identity') return shellQuote(values.domain + '\\' + values.username);
    if (key === 'principal') return cypherQuote((values.username + '@' + values.domain).toUpperCase());
    // Validated DNS and IP values are safe unquoted; usernames are shell-quoted.
    return key === 'username' ? shellQuote(values[key]) : values[key];
  });
  return {code: rendered, missing: [...required].filter(k => fieldError(k, values[k] || ''))};
};
const newLab = (id, first) => ({id, values: Object.fromEntries(labFields.map(([key]) => [key, ''])), profile: 'none', current: first, checks: {}, notes: {}});
const readLabStore = (raw, data) => {
  const state = JSON.parse(raw);
  const ids = new Set(data.workflows.map(w => w.id));
  if (state?.version !== 1 || !Array.isArray(state.labs) || !state.labs.length || typeof state.active !== 'string') throw Error('Unrecognized saved lab format');
  const unique = new Set();
  for (const lab of state.labs) {
    if (!lab || typeof lab.id !== 'string' || unique.has(lab.id) || !ids.has(lab.current) || !data.profiles.some(p => p.id === lab.profile)) throw Error('Invalid saved lab');
    unique.add(lab.id);
    if (!lab.values || labFields.some(([key]) => typeof lab.values[key] !== 'string')) throw Error('Invalid lab values');
    if (!lab.notes || !lab.checks || typeof lab.notes !== 'object' || typeof lab.checks !== 'object') throw Error('Invalid lab notes');
    for (const w of data.workflows) {
      if (lab.notes[w.id] !== undefined && typeof lab.notes[w.id] !== 'string') throw Error('Invalid note');
      if (lab.checks[w.id] !== undefined && (!Array.isArray(lab.checks[w.id]) || lab.checks[w.id].length > w.checks.length || lab.checks[w.id].some(x => typeof x !== 'boolean'))) throw Error('Invalid checklist');
    }
  }
  if (!unique.has(state.active)) throw Error('Missing active lab');
  return state;
};
const exportLabMarkdown = (lab, data) => {
  const fence = text => '`'.repeat(Math.max(3, ...((text.match(/`+/g) || []).map(x => x.length + 1))));
  const noteBlock = text => {const f = fence(text); return f + 'text\n' + text + '\n' + f;};
  const lines = ['# ' + (lab.values.name || 'Untitled lab').replace(/[\r\n]/g, ' '), '', '[Open the lab guide](https://dashboard-aed21664.mintlify.site/lab-guide)', '', '## Lab context', ''];
  for (const [key, label] of labFields) lines.push('- ' + label + ': ' + (lab.values[key] || '(not set)').replace(/[\r\n]/g, ' '));
  lines.push('', 'Current workflow: ' + data.workflows.find(w => w.id === lab.current).title, '', 'These are prepared command examples, not a record of executed commands. Checkboxes and notes are your recorded observations.');
  for (const [i, w] of data.workflows.entries()) {
    lines.push('', '## ' + (i + 1) + '. ' + w.title, '', w.goal, '');
    w.checks.forEach((check, j) => lines.push('- [' + (lab.checks[w.id]?.[j] ? 'x' : ' ') + '] ' + check));
    if (lab.notes[w.id]) lines.push('', '### My findings', '', noteBlock(lab.notes[w.id]));
    for (const c of w.commands) {const rendered = renderLabCommand(c.code, lab.values); lines.push('', c.label + (rendered.missing.length ? ' (fill placeholders before use)' : ''), '', '```' + c.language, rendered.code, '```');}
    lines.push('', ...w.links.map(l => '- [' + l.label + '](' + (l.href.startsWith('/') ? 'https://dashboard-aed21664.mintlify.site' : '') + l.href + ')'));
  }
  return lines.join('\n') + '\n';
};

// Additive fields on the established lab-guide store. Old labs remain valid.
const studyKey = 'cpts-lab-guide-v1';
const studyId = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 10);
const studyNotebook = lab => ({boxId:'',services:'',observations:'',attempts:'',nextAction:'',pins:[],reviews:[],...(lab.workspace || {})});
const studyCheck = (lab,id) => ({status:'not-checked',observation:'',reason:'',evidence:'',...(lab.evidenceChecks?.[id]||{})});
const studySetCheck = (lab,id,patch) => ({...lab,evidenceChecks:{...(lab.evidenceChecks||{}),[id]:{...studyCheck(lab,id),...patch}}});
const studyPostBox = lab => ({missedClue:'',mistakenAssumption:'',usefulCheck:'',guide:'',...(lab.workspace?.postBox||{})});
const studyExportState = (state,kind,at=new Date().toISOString()) => ({...state,lastExportRequested:{kind,at}});
const studySettings = state => ({module:'ad',lesson:'/active-directory/index',...(state.study || {})});
const studySafeHref = href => typeof href==='string' && /^\/(?!\/)[a-z0-9][a-z0-9/_-]*(?:#[^\s<>]*)?$/i.test(href);
const studyValidate = state => {
  const fail=()=>{throw Error('Invalid workspace data. Existing saved work has not been replaced.');};
  const strings=(o,keys)=>o && keys.every(k=>typeof o[k]==='string');
  const object=o=>o!==null && typeof o==='object' && !Array.isArray(o);
  if(state.lastExportRequested!==undefined && (!strings(state.lastExportRequested,['kind','at']) || !['json-download','json-copy','markdown-download'].includes(state.lastExportRequested.kind) || !Number.isFinite(Date.parse(state.lastExportRequested.at))))fail();
  if(state.study!==undefined && (!strings(state.study,['module','lesson']) || !studySafeHref(state.study.lesson)))fail();
  for(const lab of state.labs){
    if(lab.evidenceChecks!==undefined){
      if(!object(lab.evidenceChecks))fail();
      for(const [id,c] of Object.entries(lab.evidenceChecks))if(!/^[a-z][a-z0-9.-]*$/.test(id)||['constructor','prototype','__proto__'].includes(id)||!strings(c,['status','observation','reason','evidence'])||!['not-checked','tested','blocked','revisit'].includes(c.status))fail();
    }
    if(lab.workspace===undefined)continue;
    const w=lab.workspace;
    if(!strings(w,['boxId','services','observations','attempts','nextAction']) || !Array.isArray(w.pins)||!Array.isArray(w.reviews))fail();
    if(w.postBox!==undefined && (!strings(w.postBox,['missedClue','mistakenAssumption','usefulCheck','guide']) || (w.postBox.guide && !studySafeHref(w.postBox.guide))))fail();
    const hrefs=new Set(),ids=new Set();
    for(const p of w.pins){if(!strings(p,['title','href'])||!studySafeHref(p.href)||hrefs.has(p.href))fail();hrefs.add(p.href);}
    for(const r of w.reviews){if(!strings(r,['id','technique','confidence','notes','updated'])||!r.id||ids.has(r.id)||!['comfortable','help','revisit'].includes(r.confidence))fail();ids.add(r.id);}
  }return state;
};
const studyOpenBox = (state,box) => {
  const found=state.labs.find(l=>studyNotebook(l).boxId===box.id) || state.labs.find(l=>!studyNotebook(l).boxId && l.values.name.trim().toLowerCase()===box.name.toLowerCase());
  if(found)return {...state,active:found.id,labs:state.labs.map(l=>l.id===found.id?{...l,workspace:{...studyNotebook(l),boxId:box.id}}:l)};
  const lab=newLab(studyId(),'prepare');lab.values.name=box.name;lab.workspace={...studyNotebook(lab),boxId:box.id};
  return {...state,active:lab.id,labs:[...state.labs,lab]};
};
const studyPin = (state,entry) => {
  if(!studySafeHref(entry.href))throw Error('This reference cannot be saved.');
  return {...state,labs:state.labs.map(l=>{if(l.id!==state.active)return l;const w=studyNotebook(l);return {...l,workspace:{...w,pins:w.pins.some(p=>p.href===entry.href)?w.pins:[...w.pins,{title:entry.trail||entry.title,href:entry.href}]}};})};
};
const studyMerge = (current,incoming) => {
  studyValidate(incoming);
  // Imported labs always get new identities. Neither local notes nor same-name labs are overwritten.
  const labs=incoming.labs.map(l=>({...l,id:studyId(),values:{...l.values,name:(l.values.name||'Untitled lab')+' (imported)'}}));
  return {...current,active:labs[incoming.labs.findIndex(l=>l.id===incoming.active)].id,labs:[...current.labs,...labs],study:current.study||incoming.study};
};
const studyMarkdown = (lab,data=null) => {
  const w=studyNotebook(lab),line=s=>s.replace(/[\r\n]/g,' ');
  const block=s=>{const f='`'.repeat(Math.max(3,...(s.match(/`+/g)||[]).map(t=>t.length+1)));return f+'text\n'+(s||'(not recorded)')+'\n'+f;};
  const lines=['# '+line(lab.values.name||'Untitled lab'),'','## Box notebook',''];
  for(const [k,label] of [['services','Discovered services'],['observations','Observations and evidence paths'],['attempts','Attempted approaches and results'],['nextAction','Next action']])lines.push('### '+label,'',block(w[k]),'');
  lines.push('## Saved references','',...w.pins.map(p=>'- '+line(p.title)+' — https://dashboard-aed21664.mintlify.site'+p.href),'','## Revision','');
  for(const r of w.reviews)lines.push('### '+line(r.technique),'',r.confidence+' · '+r.updated,'',block(r.notes),'');
  lines.push('## Evidence checks','','Tested means performed, not a vulnerability found. Earlier checkmarks remain separate.','');
  for(const [id,c] of Object.entries(lab.evidenceChecks||{})){
    const workflow=data?.workflows.find(w=>w.checkIds?.includes(id));
    const label=workflow?workflow.checks[workflow.checkIds.indexOf(id)]:id;
    lines.push('### '+line(label),'','Check ID: '+id,'','Status: '+c.status,'','Observation:',block(c.observation),'','Reason for next step:',block(c.reason),'','Evidence reference:',block(c.evidence),'');
  }
  const post=studyPostBox(lab);lines.push('## Post-box review','');
  for(const [key,label] of [['missedClue','Missed clue'],['mistakenAssumption','Mistaken assumption'],['usefulCheck','Useful check'],['guide','Linked guide to improve']])lines.push('### '+label,'',block(post[key]),'');
  return lines.join('\n');
};

// The caller owns a session cache. Failed loads are evicted so retry is independent.
const loadSearchCollection = (cache,name,version,valid,fetcher) => {
 const key=name+'@'+version;
 if(cache.has(key))return cache.get(key);
 const pending=(async()=>{
  for(const extension of ['json','txt']){
   try{
    const response=await fetcher('/downloads/'+name+'.'+extension+'?v='+version);
    if(!response.ok)throw Error('Unavailable');
    const data=await response.json();
    if(!Array.isArray(data)||!data.every(valid))throw Error('Invalid search data');
    return data;
   }catch(error){if(extension==='txt')throw error;}
  }
 })();
 cache.set(key,pending);
 pending.catch(()=>{if(cache.get(key)===pending)cache.delete(key);});
 return pending;
};


 const [mode,setMode]=useState(initialMode);
 const [subject,setSubject]=useState('');
 const [kind,setKind]=useState('');
 const [tool,setTool]=useState('');
 const [source,setSource]=useState('');
 const [query,setQuery]=useState('');
 const [saved,setSaved]=useState(offline?savedExamples:[]);
 const [entries,setEntries]=useState(offline?searchEntries:baseEntries);
 const [status,setStatus]=useState(offline?'ready':'idle');
 const [searchStatus,setSearchStatus]=useState(offline?'ready':'idle');
 const [requested,setRequested]=useState(offline||initialMode==='notebook');
 const [searchAttempt,setSearchAttempt]=useState(0);
 const [examplesAttempt,setExamplesAttempt]=useState(0);
 const [limit,setLimit]=useState(8);
 const [notice,setNotice]=useState('');
 const [restored,setRestored]=useState(false);
 useEffect(()=>{
  const restore=()=>{
   const p=new URLSearchParams(offline?window.location.hash.split('?')[1]||'':window.location.search);
   setQuery(p.get('q')||'');setTool(p.get('tool')||'');setSubject(p.get('subject')||'');setSource(p.get('source')||'');
   setKind(['Task','Note','Section','Box','Command'].includes(p.get('type'))?p.get('type'):'');
   const view=p.get('view');setMode(['all','tools','notebook'].includes(view)?view:p.get('tool')||p.get('source')?'notebook':initialMode);
   if(p.get('q')||p.get('subject')||p.get('tool')||p.get('source')||p.get('type')||view)setRequested(true);
   setLimit(8);setRestored(true);
  };
  restore();const event=offline?'hashchange':'popstate';window.addEventListener(event,restore);return()=>window.removeEventListener(event,restore);
 },[]);
 useEffect(()=>{
  if(offline||!restored)return;
  // Let Mintlify's router preserve its own state and synchronize the new URL.
  // Reusing its internal history object bypasses that synchronization.
  const url=new URL(window.location.href),path=url.pathname;
  let changed=false;
  for(const [k,v] of Object.entries({q:query,tool,subject,source,type:kind,view:mode===initialMode?'':mode})){
   if((url.searchParams.get(k)||'')!==v){changed=true;v?url.searchParams.set(k,v):url.searchParams.delete(k);}
  }
  if(!changed)return;
  const timer=setTimeout(()=>{if(window.location.pathname===path)window.history.replaceState(null,'',url.pathname+url.search+url.hash);},200);
  return()=>clearTimeout(timer);
 },[query,mode,tool,subject,source,kind,restored]);
 useEffect(()=>{
  if(offline||!restored||!requested||mode!=='all')return;
  let active=true;
  const cache=window.__cptsSearchCollections||(window.__cptsSearchCollections=new Map());
  setSearchStatus('loading');
  loadSearchCollection(cache,'vault-primary-search',searchRevision,e=>typeof e?.title==='string'&&e.href?.startsWith('/')&&typeof e.kind==='string',url=>fetch(url))
   .then(data=>{if(active){setEntries(data);setSearchStatus('ready');}})
   .catch(()=>{if(active)setSearchStatus('error');});
  return()=>{active=false;};
 },[offline,restored,requested,mode,searchAttempt]);
 useEffect(()=>{
  if(offline||!restored||!requested||mode!=='notebook')return;
  let active=true;
  const cache=window.__cptsSearchCollections||(window.__cptsSearchCollections=new Map());
  setStatus('loading');
  loadSearchCollection(cache,'saved-command-examples',revision,e=>typeof e?.code==='string'&&e.href?.startsWith('/'),url=>fetch(url))
   .then(data=>{if(active){setSaved(data);setStatus('ready');}})
   .catch(()=>{if(active)setStatus('error');});
  return()=>{active=false;};
 },[offline,restored,requested,mode,examplesAttempt]);
 const update=value=>{setQuery(value);setRequested(true);setLimit(8);setNotice('');};
 const clear=()=>{setSubject('');setKind('');setTool('');setSource('');update('');};
 const changeMode=value=>{setMode(value);setTool('');setSource('');setKind('');setLimit(8);setRequested(true);};
 const copy=async(code)=>{try{await navigator.clipboard.writeText(code);setNotice('Copied.');}catch{setNotice('Copy unavailable here. Select the example text to copy it.');}};
 const save=entry=>{try{const raw=localStorage.getItem(studyKey),first=newLab(studyId(),'prepare');const current=raw?studyValidate(readLabStore(raw,labData)):{version:1,active:first.id,labs:[first]};const next=studyPin(current,entry);localStorage.setItem(studyKey,JSON.stringify(next));setNotice('Saved to '+(next.labs.find(l=>l.id===next.active).values.name||'your box notebook')+'.');}catch{setNotice('Could not save this reference. Open My workspace to export or recover your existing notes.');}};
 const toolSubject=slug=>baseEntries.find(e=>e.href==='/commands/'+slug)?.subject;
 const tools=mode==='tools'?(query.trim()?searchCommands(catalog,query):catalog).filter(e=>!subject||toolSubject(e.slug)===subject):[];
