 const sources=Array.from(new Map(saved.filter(e=>(!subject||e.subject===subject)&&(!tool||e.tools?.includes(tool))).map(e=>[e.route,e.page])).entries()).sort((a,b)=>a[1].localeCompare(b[1]));
 const hasQuery=!!query.trim();
