   {mode==='all'&&<label>Result type<select value={kind} onChange={e=>{setKind(e.target.value);setLimit(8);setRequested(true);}}><option value="">All types</option>{Object.entries(labels).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></label>}
   {mode==='notebook'&&<><label>Tool<select value={tool} onChange={e=>{setTool(e.target.value);setSource('');setLimit(8);}}><option value="">All tools, including unassigned examples</option>{[...catalog].sort((a,b)=>a.title.localeCompare(b.title)).map(t=><option key={t.slug} value={t.slug}>{t.title}</option>)}</select></label><label>Source note<select value={source} onChange={e=>{setSource(e.target.value);setLimit(8);}}><option value="">All source notes</option>{sources.map(([route,title])=><option key={route} value={route}>{title}</option>)}</select></label></>}
   {(hasQuery||hasFilter)&&<button type="button" onClick={clear}>Clear search and filters</button>}
